    double fc = f(c);

    // Check if we found the root within precision
    if (std::abs(fc) < precision) {
        return c;
    }

    // Determine which half contains the root
    if (fa * fc < 0) {
        b = c;
        fb = fc;
    } else {
        a = c;
        fa = fc;
    }

    // Check if interval is small enough
    if (std::abs(b - a) < precision) {
        return (a + b) / 2.0;
    }
}

